//! The per-function extender catalog (LMC-SCR-004; `docs/engine/extender-catalog.md` §1): every SKSE64, F4SE,
//! xNVSE / NVSE-plugin and OBSE function, with the version that introduced it, read from
//! `docs/data/extenders/*.tsv` (generated by `scripts/extender-catalog.py` from the extenders' published scripts and
//! changelogs and the GECK / CS wiki dumps).
//!
//! Coverage is measured, never listed by hand. A Papyrus function is served when the Papyrus VM's own checker accepts
//! a call of its declared signature ([`vm_serves`]), or when the SDK catalog classifies it `Native`
//! ([`sdk_native`]). An ObScript command is served when the SDK catalog classifies it `Native`, because the ObScript
//! VM runs no NVSE or OBSE command yet.

use std::sync::{Arc, OnceLock};

use byroredux_sdk::compatibility::{
    classify_method_call, classify_obscript_command, classify_static_call, CompatibilityDisposition,
};

/// One catalogued function.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CatalogRow {
    pub family: String,
    /// The Papyrus script declaring it; `None` for an ObScript command.
    pub script: Option<String>,
    pub function: String,
    pub signature: String,
    /// A Papyrus `Global` function (called on the script, not on an object).
    pub global: bool,
    /// The version that introduced it, as its family numbers releases.
    pub introduced: String,
    /// Where `introduced` comes from: `whatsnew:<version>`, `wiki:originVersion`, `wiki:text` or `first-release`.
    pub introduced_source: String,
}

/// The catalog's families, each with its table.
pub const FAMILIES: [(&str, &str); 11] = [
    ("skse64", include_str!("../../../docs/data/extenders/skse64.tsv")),
    ("f4se", include_str!("../../../docs/data/extenders/f4se.tsv")),
    ("xnvse", include_str!("../../../docs/data/extenders/xnvse.tsv")),
    ("jip_ln", include_str!("../../../docs/data/extenders/jip_ln.tsv")),
    ("johnnyguitar", include_str!("../../../docs/data/extenders/johnnyguitar.tsv")),
    ("showoff", include_str!("../../../docs/data/extenders/showoff.tsv")),
    ("lstewieal_tweaks", include_str!("../../../docs/data/extenders/lstewieal_tweaks.tsv")),
    ("sup", include_str!("../../../docs/data/extenders/sup.tsv")),
    ("knvse", include_str!("../../../docs/data/extenders/knvse.tsv")),
    ("mcm", include_str!("../../../docs/data/extenders/mcm.tsv")),
    ("obse", include_str!("../../../docs/data/extenders/obse.tsv")),
];

/// Every catalogued function, parsed once.
pub fn rows() -> &'static [CatalogRow] {
    static ROWS: OnceLock<Vec<CatalogRow>> = OnceLock::new();
    ROWS.get_or_init(|| FAMILIES.iter().flat_map(|(_, table)| parse(table)).collect())
}

/// Parse one table (a header line, then `family script function signature global introduced introduced_source
/// source`). A malformed line is skipped.
pub fn parse(table: &str) -> Vec<CatalogRow> {
    table
        .lines()
        .skip(1)
        .filter_map(|line| {
            let cols: Vec<&str> = line.split('\t').collect();
            let [family, script, function, signature, global, introduced, introduced_source, _source] = cols[..] else {
                return None;
            };
            Some(CatalogRow {
                family: family.to_owned(),
                script: (script != "-").then(|| script.to_owned()),
                function: function.to_owned(),
                signature: signature.to_owned(),
                global: global == "1",
                introduced: introduced.to_owned(),
                introduced_source: introduced_source.to_owned(),
            })
        })
        .collect()
}

/// Each game's script hierarchy (`script`, `parent`), from the vanilla scripts the extenders ship.
const HIERARCHIES: [(&str, &str); 2] = [
    ("skyrim", include_str!("../../../docs/data/extenders/skse64-scripts.tsv")),
    ("fo4", include_str!("../../../docs/data/extenders/f4se-scripts.tsv")),
];

/// The catalog families a game's mods call, by the preflight's game name. Fallout 3's FOSE publishes no catalogue
/// source the engine has read, and Starfield's SFSE no script sources, so both have none.
pub fn families_for_game(game: &str) -> &'static [&'static str] {
    match game {
        "skyrim" => &["skse64"],
        "fo4" => &["f4se"],
        "fnv" => &["xnvse", "jip_ln", "johnnyguitar", "showoff", "lstewieal_tweaks", "sup", "knvse", "mcm"],
        "oblivion" => &["obse"],
        _ => &[],
    }
}

/// `script`'s parent in `game`'s hierarchy (case-insensitive), if the game's vanilla scripts declare it.
fn vanilla_parent(game: &str, script: &str) -> Option<&'static str> {
    static PARSED: OnceLock<Vec<(&'static str, Vec<(String, &'static str)>)>> = OnceLock::new();
    let parsed = PARSED.get_or_init(|| {
        HIERARCHIES
            .iter()
            .map(|(game, table)| {
                let rows = table
                    .lines()
                    .skip(1)
                    .filter_map(|line| line.split_once('\t'))
                    .map(|(script, parent)| (script.to_ascii_lowercase(), parent))
                    .collect();
                (*game, rows)
            })
            .collect()
    });
    let key = script.to_ascii_lowercase();
    parsed
        .iter()
        .find(|(g, _)| *g == game)?
        .1
        .iter()
        .find(|(name, _)| *name == key)
        .map(|(_, parent)| *parent)
        .filter(|parent| !parent.is_empty())
}

/// Whether `script` is one of `game`'s vanilla scripts (or one its extender adds).
pub fn is_game_script(game: &str, script: &str) -> bool {
    HIERARCHIES.iter().any(|(g, table)| {
        *g == game && table.lines().skip(1).any(|line| line.split('\t').next().is_some_and(|name| name.eq_ignore_ascii_case(script)))
    })
}

fn find_row(game: &str, script: Option<&str>, function: &str, global: Option<bool>) -> Option<&'static CatalogRow> {
    let families = families_for_game(game);
    rows().iter().find(|row| {
        families.contains(&row.family.as_str())
            && row.function.eq_ignore_ascii_case(function)
            && match (script, &row.script) {
                (Some(want), Some(have)) => want.eq_ignore_ascii_case(have),
                (None, None) => true,
                _ => false,
            }
            && global.is_none_or(|global| global == row.global)
    })
}

/// The catalog row a compiled Papyrus call reaches, walking up from the receiver's declared type: through
/// `own_parents` (the mod's scripts, by name) and the game's vanilla hierarchy. A static call names its script; a
/// method call reaches an instance function of the receiver's type or a parent's. `None`: not an extender call, or a
/// receiver of a type neither knows.
pub fn resolve_pex_call(
    game: &str,
    call: &byroredux_pex::CallSite,
    own_parents: &dyn Fn(&str) -> Option<String>,
) -> Option<&'static CatalogRow> {
    let is_static = matches!(call.target, byroredux_pex::CallTarget::StaticType(_));
    let mut script = call.receiver_type.clone()?;
    for _ in 0..32 {
        if let Some(row) = find_row(game, Some(&script), &call.function, Some(is_static)) {
            return Some(row);
        }
        if is_static {
            return None;
        }
        script = match own_parents(&script).filter(|parent| !parent.is_empty()) {
            Some(parent) => parent,
            None => vanilla_parent(game, &script)?.to_owned(),
        };
    }
    None
}

/// The catalogued commands an ObScript source calls: each identifier that names a command of the game's families
/// (case-insensitive), comments and quoted strings skipped. A variable spelled like a command would be counted; NVSE
/// and OBSE command names are rarely reused as variable names.
pub fn obscript_source_calls(game: &str, source: &str) -> Vec<&'static CatalogRow> {
    let families = families_for_game(game);
    if families.is_empty() {
        return Vec::new();
    }
    let mut calls = Vec::new();
    for line in source.lines() {
        let mut code = String::new();
        let mut quoted = false;
        for c in line.chars() {
            match c {
                '"' => quoted = !quoted,
                ';' if !quoted => break,
                _ if !quoted => code.push(c),
                _ => {}
            }
        }
        for word in code.split(|c: char| !(c.is_ascii_alphanumeric() || c == '_')).filter(|w| !w.is_empty()) {
            if let Some(row) = find_row(game, None, word, None) {
                calls.push(row);
            }
        }
    }
    calls
}

/// [`served`], measured once per row.
pub fn served_cached(row: &'static CatalogRow) -> bool {
    use std::collections::HashMap;
    use std::sync::Mutex;
    static CACHE: OnceLock<Mutex<HashMap<usize, bool>>> = OnceLock::new();
    let key = row as *const CatalogRow as usize;
    let cache = CACHE.get_or_init(Default::default);
    if let Some(served) = cache.lock().ok().and_then(|cache| cache.get(&key).copied()) {
        return served;
    }
    let value = served(row);
    if let Ok(mut cache) = cache.lock() {
        cache.insert(key, value);
    }
    value
}

/// A Papyrus signature `ret Name(type a, type b = 1)`: its return type and parameter types.
fn papyrus_signature(signature: &str) -> Option<(String, Vec<String>)> {
    let open = signature.find('(')?;
    let close = signature.rfind(')')?;
    let head: Vec<&str> = signature[..open].split_whitespace().collect();
    let ret = if head.len() >= 2 { head[0].to_owned() } else { "None".to_owned() };
    let params = signature[open + 1..close]
        .split(',')
        .map(|param| param.split('=').next().unwrap_or("").trim())
        .filter(|param| !param.is_empty())
        .map(|param| param.split_whitespace().next().unwrap_or("").to_owned())
        .collect();
    Some((ret, params))
}

/// A value of Papyrus type `ty` for a probe call.
fn placeholder(ty: &str) -> &'static str {
    match ty.to_ascii_lowercase().as_str() {
        "int" => "0",
        "float" => "0.0",
        "bool" => "False",
        "string" => "\"\"",
        _ => "None",
    }
}

/// The probe script calling `row` with typed placeholders: the call the VM must accept to serve it.
fn probe_source(row: &CatalogRow) -> Option<String> {
    let script = row.script.as_deref()?;
    let (ret, params) = papyrus_signature(&row.signature)?;
    let mut body = String::new();
    let mut args = Vec::new();
    for (index, ty) in params.iter().enumerate() {
        body.push_str(&format!(" {ty} a{index} = {}\n", placeholder(ty)));
        args.push(format!("a{index}"));
    }
    let receiver = if row.global {
        script.to_owned()
    } else {
        body.push_str(&format!(" {script} akReceiver = None\n"));
        "akReceiver".to_owned()
    };
    let call = format!("{receiver}.{}({})", row.function, args.join(", "));
    if ret.eq_ignore_ascii_case("none") {
        body.push_str(&format!(" {call}\n"));
    } else {
        body.push_str(&format!(" {ret} r = {call}\n"));
    }
    Some(format!("ScriptName ExtenderCatalogProbe extends Quest\nFunction Probe()\n{body}EndFunction\n"))
}

/// Whether the Papyrus VM's checker accepts a call of `row`'s declared signature.
pub fn vm_serves(row: &CatalogRow) -> bool {
    let Some(source) = probe_source(row) else { return false };
    let Ok((script, errors)) = byroredux_papyrus::parse_script(&source) else { return false };
    if !errors.is_empty() {
        return false;
    }
    crate::fragment::vm::check_function_reason(Arc::new(script), "Probe", None).is_ok()
}

/// Whether the SDK catalog classifies `row` `Native` (an adapter executes it).
pub fn sdk_native(row: &CatalogRow) -> bool {
    let matched = match (&row.script, row.global) {
        (None, _) => classify_obscript_command(&row.function),
        (Some(script), true) => classify_static_call(script, &row.function),
        (Some(_), false) => classify_method_call(&row.function),
    };
    matched.is_some_and(|m| m.disposition == CompatibilityDisposition::Native)
}

/// Whether the engine serves `row` by either path.
pub fn served(row: &CatalogRow) -> bool {
    sdk_native(row) || (row.script.is_some() && vm_serves(row))
}

/// One family's coverage: functions catalogued, those with a documented introducing version, and those served
/// (by the VM, by the SDK, by either).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Coverage {
    pub functions: usize,
    pub dated: usize,
    pub vm: usize,
    pub sdk: usize,
    pub served: usize,
}

/// Every family's coverage, in [`FAMILIES`] order.
pub fn coverage() -> Vec<(&'static str, Coverage)> {
    FAMILIES
        .iter()
        .map(|(family, _)| {
            let mut coverage = Coverage::default();
            for row in rows().iter().filter(|row| row.family == *family) {
                let vm = row.script.is_some() && vm_serves(row);
                let sdk = sdk_native(row);
                coverage.functions += 1;
                coverage.dated += usize::from(row.introduced_source != "first-release");
                coverage.vm += usize::from(vm);
                coverage.sdk += usize::from(sdk);
                coverage.served += usize::from(vm || sdk);
            }
            (*family, coverage)
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_table_parses_whole() {
        for (family, table) in FAMILIES {
            let lines = table.lines().skip(1).filter(|line| !line.is_empty()).count();
            let parsed = parse(table);
            assert_eq!(parsed.len(), lines, "{family}: every line is a row");
            assert!(parsed.iter().all(|row| row.family == family), "{family}: rows name their family");
        }
        assert!(rows().len() > 3000);
    }

    #[test]
    fn signatures_split_into_return_and_parameter_types() {
        assert_eq!(papyrus_signature("int GetPluginVersion(string name)"), Some(("int".into(), vec!["string".into()])));
        assert_eq!(papyrus_signature("None QueueNiNodeUpdate()"), Some(("None".into(), vec![])));
        assert_eq!(
            papyrus_signature("Form[] Find(Form a, int b = 0, bool c = False)"),
            Some(("Form[]".into(), vec!["Form".into(), "int".into(), "bool".into()]))
        );
    }

    #[test]
    fn a_probe_calls_the_function_as_declared() {
        let row = |script: &str, function: &str, signature: &str, global: bool| CatalogRow {
            family: "skse64".into(),
            script: Some(script.into()),
            function: function.into(),
            signature: signature.into(),
            global,
            introduced: "1.1.0".into(),
            introduced_source: "first-release".into(),
        };
        let instance = probe_source(&row("Actor", "GetWornForm", "Form GetWornForm(int slotMask)", false)).unwrap();
        assert!(instance.contains(" int a0 = 0\n Actor akReceiver = None\n Form r = akReceiver.GetWornForm(a0)\n"), "{instance}");
        let global = probe_source(&row("Game", "GetModCount", "int GetModCount()", true)).unwrap();
        assert!(global.contains(" int r = Game.GetModCount()\n"), "{global}");
    }

    fn call(target: byroredux_pex::CallTarget, receiver: Option<&str>, function: &str) -> byroredux_pex::CallSite {
        byroredux_pex::CallSite {
            source_file: "Test.psc".into(),
            object: "Test".into(),
            scope: byroredux_pex::CallScope::StateFunction { state: String::new(), function: "F".into() },
            instruction_index: 0,
            source_line: None,
            target,
            function: function.into(),
            argument_count: 0,
            receiver_type: receiver.map(str::to_owned),
        }
    }

    #[test]
    fn a_method_call_resolves_through_the_receivers_hierarchy() {
        use byroredux_pex::CallTarget;
        let none = |_: &str| None;
        // SKSE adds GetName to Form; an Actor receiver reaches it through ObjectReference and Form.
        let row = resolve_pex_call("skyrim", &call(CallTarget::Receiver(Some("akActor".into())), Some("Actor"), "GetName"), &none).unwrap();
        assert_eq!((row.family.as_str(), row.script.as_deref(), row.function.as_str()), ("skse64", Some("Form"), "GetName"));
        // A mod script extending Actor reaches it too, through the mod's own declaration.
        let mine = |script: &str| script.eq_ignore_ascii_case("MyFollower").then(|| "Actor".to_owned());
        assert!(resolve_pex_call("skyrim", &call(CallTarget::Receiver(None), Some("MyFollower"), "GetName"), &mine).is_some());
        // A vanilla function is no extender call, and an unknown receiver type resolves nothing.
        assert!(resolve_pex_call("skyrim", &call(CallTarget::Receiver(None), Some("Actor"), "GetActorValue"), &none).is_none());
        assert!(resolve_pex_call("skyrim", &call(CallTarget::Receiver(None), Some("Unknown"), "GetName"), &none).is_none());
        assert!(resolve_pex_call("skyrim", &call(CallTarget::Receiver(None), None, "GetName"), &none).is_none());
        // A static call names its script exactly.
        let split = resolve_pex_call("skyrim", &call(CallTarget::StaticType("StringUtil".into()), Some("StringUtil"), "Split"), &none).unwrap();
        assert_eq!((split.script.as_deref(), split.introduced.as_str()), (Some("StringUtil"), "1.7.3"));
        assert!(resolve_pex_call("fo4", &call(CallTarget::StaticType("StringUtil".into()), Some("StringUtil"), "Split"), &none).is_none(), "per game");
    }

    #[test]
    fn obscript_source_calls_are_the_catalogued_commands() {
        let calls = obscript_source_calls(
            "fnv",
            "scn Test\nbegin GameMode\n if IsModLoaded \"x.esp\" ; GetNVSEVersion in a comment\n  set v to GetNVSEVersion\n  PrintC \"IsModLoaded %g\" v\n endif\nend\n",
        );
        let names: Vec<_> = calls.iter().map(|row| row.function.as_str()).collect();
        assert!(names.contains(&"IsModLoaded") && names.contains(&"GetNVSEVersion"), "{names:?}");
        assert_eq!(names.iter().filter(|n| n.eq_ignore_ascii_case("IsModLoaded")).count(), 1, "not inside a string");
        assert!(obscript_source_calls("fo3", "GetNVSEVersion").is_empty(), "no FOSE catalogue");
    }

    /// The coverage `docs/engine/extender-catalog.md` §5 publishes: a change to the catalog or to what the engine
    /// serves moves these, and the document with them.
    #[test]
    fn coverage_counts_are_the_published_ones() {
        let published: [(&str, Coverage); 11] = [
            ("skse64", Coverage { functions: 804, dated: 67, vm: 15, sdk: 21, served: 26 }),
            ("f4se", Coverage { functions: 227, dated: 13, vm: 1, sdk: 3, served: 4 }),
            ("xnvse", Coverage { functions: 565, dated: 50, vm: 0, sdk: 4, served: 4 }),
            ("jip_ln", Coverage { functions: 733, dated: 0, vm: 0, sdk: 0, served: 0 }),
            ("johnnyguitar", Coverage { functions: 142, dated: 31, vm: 0, sdk: 0, served: 0 }),
            ("showoff", Coverage { functions: 122, dated: 69, vm: 0, sdk: 0, served: 0 }),
            ("lstewieal_tweaks", Coverage { functions: 282, dated: 0, vm: 0, sdk: 0, served: 0 }),
            ("sup", Coverage { functions: 182, dated: 0, vm: 0, sdk: 0, served: 0 }),
            ("knvse", Coverage { functions: 4, dated: 0, vm: 0, sdk: 0, served: 0 }),
            ("mcm", Coverage { functions: 4, dated: 0, vm: 0, sdk: 0, served: 0 }),
            ("obse", Coverage { functions: 644, dated: 92, vm: 0, sdk: 5, served: 5 }),
        ];
        let measured = coverage();
        for ((family, numbers), (published_family, published_numbers)) in measured.iter().zip(published.iter()) {
            assert_eq!(family, published_family);
            assert_eq!(numbers, published_numbers, "{family}: update extender-catalog.md §5 and this table together");
        }
    }
}
